kodas.handle_save:
public static function handle_save( $request ) {
	$user_id = get_current_user_id();
	if ( ! $user_id ) {
		return new WP_Error( 'not_logged_in', 'Reikia prisijungti.', array( 'status' => 401 ) );
	}
	$pet_id = (int) $request->get_param( 'pet_id' );
	if ( $pet_id > 0 ) {
		$input = self::sanitize_input( $request, true );
		return self::update_pet( $user_id, $pet_id, $input );
	}
	$input = self::sanitize_input( $request, false );
	$client_ref = self::extract_client_ref( $request );
	$force_new = (bool) $request->get_param( 'force_new' );
	return self::create_pet( $user_id, $input, $client_ref, $force_new );
}

/**
 * PATCH /pet-profile/{id} — dalinis update (tik perduoti laukai).
 */

kodas.sanitize_input:
private static function sanitize_input( $request, $partial = false ) {
	$out = array();
	$fields = array(
		'species', 'species_detail', 'pet_name', 'life_stage', 'dog_size',
		'is_sterilised', 'feeding_type', 'feeding_type_other', 'wet_food_g', 'wet_product_id',
		'primary_need', 'primary_need_other', 'current_food_brand',
		'birth_date', 'sensitivities', 'housing', 'activity_hint',
		'current_food_free_text', 'primary_product_id',
		// S211: produkto tapatybe (snapshot)
		'primary_product_sku', 'primary_product_name', 'primary_product_package',
	);

	foreach ( $fields as $f ) {
		$raw = $request->get_param( $f );
		if ( $partial && $raw === null ) {
			continue;
		}

		switch ( $f ) {
			case 'species':
				$v = sanitize_text_field( (string) $raw );
				if ( in_array( $v, self::SPECIES, true ) ) {
					$out['species'] = $v;
				} elseif ( ! $partial ) {
					$out['species'] = 'other';
				}
				break;
			case 'pet_name':
				$out['pet_name'] = ( $raw !== null && $raw !== '' ) ? sanitize_text_field( (string) $raw ) : null;
				break;
			case 'species_detail':
				$out['species_detail'] = ( $raw !== null && $raw !== '' ) ? sanitize_text_field( (string) $raw ) : null;
				break;
			case 'current_food_brand':
				$out['current_food_brand'] = ( $raw !== null && $raw !== '' ) ? sanitize_text_field( (string) $raw ) : null;
				break;
			case 'current_food_free_text':
				$out['current_food_free_text'] = ( $raw !== null && $raw !== '' ) ? sanitize_text_field( (string) $raw ) : null;
				break;
			case 'primary_product_id':
				// S246: keiciant produkta SERVERIS pats persirašo snapshot'ą.
				// Anksciau primary_product_name/_sku/_package buvo leidziamu laukų
				// sąraše, bet sanitize jiems neturėjo case — todėl tyliai
				// nukrisdavo: ID pasikeisdavo, o profilyje ir Mityboje likdavo
				// SENAS pavadinimas. Dabar snapshot'as visada suderintas su ID.
				$ppid = $raw ? (int) $raw : null;
				$out['primary_product_id'] = $ppid;
				if ( $ppid && function_exists( 'wc_get_product' ) ) {
					$pobj = wc_get_product( $ppid );
					if ( $pobj ) {
						$parent = $pobj->is_type( 'variation' ) ? (int) $pobj->get_parent_id() : $ppid;
						$pak = wp_get_object_terms( $ppid, 'pa_pakuotes_dydis', array( 'fields' => 'names' ) );
						if ( is_wp_error( $pak ) || ! $pak ) {
							$pak = wp_get_object_terms( $parent, 'pa_pakuotes_dydis', array( 'fields' => 'names' ) );
						}
						$out['primary_product_name']    = mb_substr( (string) $pobj->get_name(), 0, 255 );
						$out['primary_product_sku']     = mb_substr( (string) $pobj->get_sku(), 0, 64 );
						$out['primary_product_package'] = ( ! is_wp_error( $pak ) && $pak ) ? mb_substr( $pak[0], 0, 64 ) : null;
					}
				} elseif ( ! $ppid ) {
					// Nutraukus rysi su produktu — snapshot'as irgi valomas.
					$out['primary_product_name']    = null;
					$out['primary_product_sku']     = null;
					$out['primary_product_package'] = null;
				}
				break;
			case 'birth_date':
				// Y-m-d, reali data, ne ateitis, ne senesne nei 1985.
				$v = sanitize_text_field( (string) $raw );
				$ok = null;
				if ( preg_match( '/^\d{4}-\d{2}-\d{2}$/', $v ) ) {
					$ts = strtotime( $v . ' 00:00:00' );
					if ( $ts && $ts <= time() && (int) substr( $v, 0, 4 ) >= 1985 ) {
						$ok = $v;
					}
				}
				$out['birth_date'] = $ok;
				break;
			case 'sensitivities':
				// CSV kodai + galimas "other:tekstas". Max 255.
				$out['sensitivities'] = ( $raw !== null && $raw !== '' ) ? substr( sanitize_text_field( (string) $raw ), 0, 255 ) : null;
				break;
			case 'housing':
				$out['housing'] = self::validate_enum( $raw, self::HOUSING );
				break;
			case 'activity_hint':
				$out['activity_hint'] = self::validate_enum( $raw, self::ACTIVITY );
				break;
			case 'life_stage':
				$out['life_stage'] = self::validate_enum( $raw, self::LIFE_STAGE );
				break;
			case 'dog_size':
				$out['dog_size'] = self::validate_enum( $raw, self::DOG_SIZE );
				break;
			case 'is_sterilised':
				$out['is_sterilised'] = self::validate_enum( $raw, self::IS_STERILISED );
				break;
			case 'feeding_type':
				$out['feeding_type'] = self::validate_enum( $raw, self::FEEDING_TYPE );
				break;
			case 'primary_need':
				$out['primary_need'] = self::validate_enum( $raw, self::PRIMARY_NEED );
				break;
			case 'feeding_type_other':
				$ft = ( $raw === null ) ? '' : trim( wp_strip_all_tags( (string) $raw ) );
				$out['feeding_type_other'] = ( $ft !== '' )
					? mb_substr( sanitize_text_field( $ft ), 0, 150 )
					: null;
				break;
			case 'wet_product_id':
				// Paprasto produkto ARBA variacijos ID (tai, kas dedama i krepseli).
				$wp = ( $raw === null || $raw === '' ) ? null : (int) $raw;
				$out['wet_product_id'] = ( $wp !== null && $wp > 0 ) ? $wp : null;
				break;
			case 'wet_food_g':
				// Realus slapio maisto kiekis gramais. 0 arba tuscias -> NULL.
				// Virsutine riba 3000 g — praktiskai neribojam, bet apsaugom nuo absurdo.
				$wg = ( $raw === null || $raw === '' ) ? null : (int) $raw;
				$out['wet_food_g'] = ( $wg !== null && $wg > 0 ) ? min( $wg, 3000 ) : null;
				break;
			case 'primary_need_other':
				// Tik paprastas tekstas, be HTML, iki 150 simboliu. Tuscias -> NULL.
				$txt = ( $raw === null ) ? '' : trim( wp_strip_all_tags( (string) $raw ) );
				$out['primary_need_other'] = ( $txt !== '' )
					? mb_substr( sanitize_text_field( $txt ), 0, 150 )
					: null;
				break;
		}
	}

	// "Kita" tekstas prasmingas TIK su primary_need='other'. Pasirinkus bet kuri kita
	// varianta (ar 'none') — isvalom, kad ataskaitoje neliktu nasleliu is senos busenos.
	// array_key_exists (ne isset), nes primary_need gali buti teisetai NULL.
	if ( array_key_exists( 'primary_need', $out ) && $out['primary_need'] !== 'other' ) {
		$out['primary_need_other'] = null;
	}

	// Tos pacios taisykles maitinimo tipui:
	//  - laisvas tekstas prasmingas TIK su feeding_type='other'
	//  - slapio maisto kiekis prasmingas TIK su feeding_type='dry_wet'
	//    (naminiam maistui / BARF perskaiciavimo nedarom, tad kiekio nesaugom)
	if ( array_key_exists( 'feeding_type', $out ) ) {
		$ft = $out['feeding_type'];
		if ( $ft !== 'other' ) { $out['feeding_type_other'] = null; }
		// Slapio KIEKIS prasmingas ir dry_wet (misriam iverciui), ir wet_only (visam planui).
		if ( $ft !== 'dry_wet' && $ft !== 'wet_only' ) { $out['wet_food_g'] = null; }
		// Slapio PRODUKTAS — tose paciose dviejose busenose.
		if ( $ft !== 'dry_wet' && $ft !== 'wet_only' ) { $out['wet_product_id'] = null; }
	}

	if ( ! $partial && ! isset( $out['species'] ) ) {
		$out['species'] = 'other';
	}
	return $out;
}

kodas.extract_client_ref:
private static function extract_client_ref( $request ) {
	$ref = $request->get_param( 'client_ref' );
	if ( ! $ref ) {
		return null;
	}
	$ref = sanitize_text_field( (string) $ref );
	// Tik saugus simboliai, max 64
	$ref = preg_replace( '/[^A-Za-z0-9_\-]/', '', $ref );
	return substr( $ref, 0, 64 ) ?: null;
}

kodas.create_pet:
private static function create_pet( $user_id, $input, $client_ref = null, $force_new = false ) {
	global $wpdb;
	$now = gmdate( 'Y-m-d H:i:s' );

	// Idempotentiskumas: jei toks client_ref jau perkeltas siam vartotojui -> grazinam esama
	// (pakartotinis magic link paspaudimas nekuria dublikato).
	if ( $client_ref ) {
		$existing_id = (int) $wpdb->get_var( $wpdb->prepare(
			"SELECT id FROM `" . self::table_name() . "` WHERE user_id = %d AND client_ref = %s AND status='active' LIMIT 1",
			$user_id, $client_ref
		) );
		if ( $existing_id ) {
			return rest_ensure_response( array(
				'ok'          => true,
				'pet_id'      => $existing_id,
				'deduplicated'=> true,
				'pet'         => self::get_pet( $existing_id ),
			) );
		}
	}

	// S206: semantinis dublikatas. client_ref apsaugo tik nuo TO PATIES juodrascio —
	// tas pats augintinis is kito irenginio turi klausti vartotojo, ne atsirasti tyliai.
	if ( ! $force_new && ! empty( $input['pet_name'] ) ) {
		$candidates = self::find_duplicate_candidates(
			$user_id,
			$input['pet_name'],
			isset( $input['species'] ) ? $input['species'] : null
		);
		if ( ! empty( $candidates ) ) {
			return new WP_REST_Response( array(
				'ok'                   => false,
				'code'                 => 'duplicate_candidate',
				'message'              => 'Rastas galimas dublikatas — reikia vartotojo sprendimo.',
				'duplicate_candidates' => $candidates,
			), 409 );
		}
	}

	$existing_count = (int) $wpdb->get_var( $wpdb->prepare(
		"SELECT COUNT(*) FROM `" . self::table_name() . "` WHERE user_id = %d AND status='active'",
		$user_id
	) );
	$is_primary = ( $existing_count === 0 ) ? 1 : 0;

	$data = array_merge( array(
		'user_id'    => $user_id,
		'is_primary' => $is_primary,
		'status'     => 'active',
		'client_ref' => $client_ref,
		'created_at' => $now,
		'updated_at' => $now,
	), $input );

	$wpdb->insert( self::table_name(), $data );
	$pet_id = (int) $wpdb->insert_id;

	if ( ! $pet_id ) {
		return new WP_Error( 'create_failed', 'Nepavyko išsaugoti anketos.', array( 'status' => 500 ) );
	}

	// S205: upsert PIRMA, event'as PO — subscriber turi egzistuoti pries atkeliaujant event'ui.
	if ( $is_primary ) {
		self::mirror_to_sender( $user_id, $pet_id );
	}
	self::emit_created( $user_id, $pet_id, $input );

	return rest_ensure_response( array(
		'ok'         => true,
		'pet_id'     => $pet_id,
		'is_primary' => (bool) $is_primary,
		'pet'        => self::get_pet( $pet_id ),
	) );
}

kodas.emit_created:
private static function emit_created( $user_id, $pet_id, $input ) {
	if ( ! class_exists( 'Petshop_Event_Registry' ) ) {
		return;
	}
	$user = get_user_by( 'id', $user_id );
	if ( ! $user ) {
		return;
	}
	Petshop_Event_Registry::emit( 'pet_profile_created', $user->user_email, array(
		'pet_id'             => $pet_id,
		'pet_name'           => $input['pet_name'] ?? null,
		'species'            => $input['species'] ?? 'other',
		'life_stage'         => $input['life_stage'] ?? null,
		'dog_size'           => $input['dog_size'] ?? null,
		'feeding_type'       => $input['feeding_type'] ?? null,
		'primary_need'       => $input['primary_need'] ?? null,
		'current_food_brand' => $input['current_food_brand'] ?? null,
	), array( 'event_id' => 'pet_created_' . $pet_id ) );
}

kodas.mirror_to_sender:
	private static function mirror_to_sender( $user_id, $pet_id ) {
		if ( ! function_exists( 'ps_esp_adapter' ) ) {
			return;
		}
		$user = get_user_by( 'id', $user_id );
		if ( ! $user ) {
			return;
		}
		$pet = self::get_pet( $pet_id );
		if ( ! $pet ) {
			return;
		}
		$adapter = ps_esp_adapter();
		if ( ! $adapter || ! $adapter->is_configured() ) {
			return;
		}
		$attrs = array(
			'PS_PET_SPECIES'    => $pet->species,
			'PS_PET_NAME'       => $pet->pet_name ?: '',
			'PS_PET_LIFE_STAGE' => $pet->life_stage ?: '',
			'PS_DOG_SIZE'       => $pet->dog_size ?: '',
			'PS_FEEDING_TYPE'   => $pet->feeding_type ?: '',
			'PS_PRIMARY_NEED'   => $pet->primary_need ?: '',
		);
		if ( $pet->current_food_brand ) {
			$attrs['PS_CURRENT_FOOD_BRAND'] = $pet->current_food_brand;
		}
		$adapter->upsert_contact( $user->user_email, $attrs );
	}
}
